def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = [(r, row[0]) for r, row in enumerate(grid)
             if row[0] != 0 and all(v == row[0] for v in row)]

    # Find the smallest period consistent with the marker rows.
    period = h
    for p in range(1, h + 1):
        if all((a - b) % p != 0 or ca == cb
               for i, (a, ca) in enumerate(marks)
               for b, cb in marks[i + 1:]):
            period = p
            break

    residues = {}
    for r, c in marks:
        residues[r % period] = c

    ordered = []
    for _, c in marks:
        if c not in ordered:
            ordered.append(c)

    # Fill unmarked positions by cycling through the observed colors in
    # marker order, while honoring all directly constrained residues.
    result = []
    for r in range(h):
        k = r % period
        if k in residues:
            c = residues[k]
        else:
            c = ordered[k % len(ordered)]
        result.append([c] * w)
    return result
